insert into public.event_quiz_questions
  (id, day_no, kind, difficulty, module, topic, prompt, options, answer_index, explanation, source, origin)
values
  ('D1-001', 1, 'main', 1, 'Geoscience', null, 'Seismic energy reflects at a boundary where which property changes?', '["Bed thickness","Rock colour","Acoustic impedance","Rock age"]'::jsonb, 2, 'A reflection needs a contrast in acoustic impedance, the product of velocity and density.', 'nextgen', 'nextgen:seismolord/beginner/m04-reflection-coefficients/1'),
  ('D1-002', 1, 'main', 1, 'Geoscience', null, 'On a seismic section, the vertical axis is usually what?', '["One-way travel time","Two-way travel time","Distance along the line","Measured depth"]'::jsonb, 1, 'Seismic is recorded in two-way time: down to the reflector and back up.', 'nextgen', 'nextgen:seismolord/beginner/m01-seismic-and-the-well-tie/1'),
  ('D1-003', 1, 'main', 1, 'Geoscience', null, 'Going down a well, which log response most often marks the top of a clean sand?', '["A jump in the caliper","A sharp drop in gamma ray","A sharp rise in gamma ray","A flat resistivity curve"]'::jsonb, 1, 'Clean sands carry little radioactive clay, so the gamma ray drops on entering them.', 'nextgen', 'nextgen:wellcorrelation/beginner/m02-formation-tops/5'),
  ('D1-004', 1, 'main', 1, 'Geoscience', null, 'Which three things must a petroleum trap have?', '["Fault, fold and salt","Porosity, water and gas","Source, well and pipeline","Reservoir, seal and a trapping shape"]'::jsonb, 3, 'A trap is a reservoir rock under a seal, in a geometry that stops hydrocarbons escaping.', 'petrolord', null),
  ('D1-005', 1, 'main', 1, 'Geoscience', null, 'Where was oil first found in commercial quantity in Nigeria, in 1956?', '["Escravos","Oloibiri","Forcados","Bonny"]'::jsonb, 1, 'Shell-BP found oil at Oloibiri, in present-day Bayelsa State, in 1956.', 'petrolord', null),
  ('D1-006', 1, 'main', 1, 'Geoscience', null, 'What does a caliper log measure?', '["Formation resistivity","Natural radioactivity","The borehole diameter","Rock density"]'::jsonb, 2, 'The caliper measures hole size, which shows washouts and mudcake.', 'nextgen', 'nextgen:petrophysics/beginner/m01-logs-and-the-typewell/8'),
  ('D1-007', 1, 'main', 1, 'Economics', null, 'In exploration, what is a dry hole?', '["A well with no casing","A well drilled without mud","A well that finds no commercial hydrocarbons","A well that makes only gas"]'::jsonb, 2, 'A dry hole is a well that does not find hydrocarbons worth producing.', 'petrolord', null),
  ('D1-008', 1, 'main', 1, 'Geoscience', null, 'Which rock is the classic seal above many oil fields?', '["Reef limestone","Shale","Clean sandstone","Conglomerate"]'::jsonb, 1, 'Fine-grained shale has very low permeability, so it holds hydrocarbons in.', 'petrolord', null),
  ('D1-009', 1, 'main', 2, 'Geoscience', null, 'In the Niger Delta, which formation holds most of the oil and gas reservoirs?', '["Benin Formation","Agbada Formation","Akata Formation","Bima Formation"]'::jsonb, 1, 'The paralic sands of the Agbada Formation are the main reservoirs; Akata shales lie below and Benin sands above.', 'petrolord', null),
  ('D1-010', 1, 'main', 2, 'Geoscience', null, 'What makes a good marker bed for well correlation?', '["Shallow, flat and unfaulted","Subtle, local and precisely dated","Distinctive, widespread and easy to recognise","Thick, porous and oil bearing"]'::jsonb, 2, 'A marker has to be picked with confidence in every well, so it must be distinctive and widespread.', 'nextgen', 'nextgen:wellcorrelation/beginner/m02-formation-tops/6'),
  ('D1-011', 1, 'main', 2, 'Geoscience', null, 'Matrix density 2.65 g/cc, fluid 1.0 g/cc, log reading 2.32 g/cc. What is the density porosity?', '["20%","33%","25%","10%"]'::jsonb, 0, '(2.65 - 2.32) / (2.65 - 1.0) = 0.33 / 1.65 = 0.20.', 'nextgen', 'nextgen:petrophysics/beginner/m03-porosity/4'),
  ('D1-012', 1, 'main', 2, 'Geoscience', null, 'A reflector is 1500 m deep with an average velocity of 2000 m/s. What is its two-way time?', '["1500 ms","3000 ms","0.75 ms","750 ms"]'::jsonb, 0, 'Two-way time = 2 x 1500 / 2000 = 1.5 s.', 'nextgen', 'nextgen:seismolord/beginner/m03-depth-to-time/4'),
  ('D1-013', 1, 'main', 2, 'Drilling', null, 'What is a kick?', '["Formation fluid flowing into the well unplanned","A sudden rise in drilling speed","A planned bit change","A stuck drill string"]'::jsonb, 0, 'A kick happens when formation pressure exceeds the mud pressure and fluid enters the well.', 'petrolord', null),
  ('D1-014', 1, 'main', 2, 'Economics', null, 'How is the chance of geological success for a prospect usually found?', '["Take the lowest element alone","Multiply the chances of each play element","Average the elements","Add the chances of each element"]'::jsonb, 1, 'Source, reservoir, trap and seal must all work, so their chances multiply.', 'petrolord', null),
  ('D1-015', 1, 'main', 2, 'Economics', null, 'Under SPE-PRMS, oil that is discovered but not yet commercial is classed as what?', '["Proved Reserves","Contingent Resources","Unrecoverable volumes","Prospective Resources"]'::jsonb, 1, 'Discovered, sub-commercial volumes are Contingent Resources; undiscovered ones are Prospective.', 'petrolord', null),
  ('D1-016', 1, 'main', 2, 'Geoscience', null, 'Gamma ray clean line 20 API, shale line 120 API, reading 70 API. What is the gamma ray index?', '["0.70","0.58","0.35","0.50"]'::jsonb, 3, '(70 - 20) / (120 - 20) = 0.50.', 'nextgen', 'nextgen:petrophysics/beginner/m02-shale-volume/6'),
  ('D1-017', 1, 'main', 2, 'Geoscience', null, 'What does a seismic bright spot often indicate?', '["A volcanic dyke","A dry well","A salt dome","Gas in a porous sand"]'::jsonb, 3, 'Gas lowers a sand''s impedance, which can give a strong amplitude. Wet sands and coals can mimic it.', 'petrolord', null),
  ('D1-018', 1, 'main', 2, 'Assurance', null, 'Under the Petroleum Industry Act 2021, which body regulates upstream oil and gas?', '["NNPC Limited","NUPRC","NCDMB","NMDPRA"]'::jsonb, 1, 'The Nigerian Upstream Petroleum Regulatory Commission regulates the upstream.', 'petrolord', null),
  ('D1-019', 1, 'main', 2, 'Geoscience', null, 'Why do oil and gas migrate upwards through rock?', '["They are less dense than formation water","They are hotter than the rock","The drill bit pushes them","Faults attract them"]'::jsonb, 0, 'Buoyancy drives migration: hydrocarbons are lighter than the water in the pores.', 'petrolord', null),
  ('D1-020', 1, 'main', 3, 'Geoscience', null, 'Shale of impedance 7000 overlies a tight carbonate of 11000. What is the reflection?', '["+0.44, a hard event","-0.22, a soft event","+0.22, a hard event","+4000, a hard event"]'::jsonb, 2, '(11000 - 7000) / (11000 + 7000) = +0.22, an increase in impedance.', 'nextgen', 'nextgen:seismolord/beginner/m04-reflection-coefficients/11'),
  ('D1-021', 1, 'main', 3, 'Geoscience', null, 'Oil generation usually begins at a vitrinite reflectance of about what?', '["4 to 5%","2.0 to 2.5%","0.5 to 0.6%","0.1 to 0.2%"]'::jsonb, 2, 'The oil window is usually taken to start around 0.5 to 0.6% Ro.', 'petrolord', null),
  ('D1-022', 1, 'main', 3, 'Geoscience', null, 'Archie: porosity 0.20, Rt 20 ohm.m, Rw 0.05, a 1, m 2, n 2. What is Sw?', '["50%","12.5%","6%","25%"]'::jsonb, 3, 'Sw = sqrt(0.05 / (0.04 x 20)) = sqrt(0.0625) = 0.25.', 'nextgen', 'nextgen:petrophysics/beginner/m04-resistivity-and-saturation/9'),
  ('D1-023', 1, 'main', 3, 'Economics', null, 'A prospect has a 30% chance of +$100M and a 70% chance of -$20M. What is its EMV?', '["+$30M","+$80M","-$14M","+$16M"]'::jsonb, 3, '0.3 x 100 - 0.7 x 20 = 30 - 14 = +$16M.', 'petrolord', null),
  ('D1-024', 1, 'main', 3, 'Geoscience', null, 'Which kerogen type, from woody land plants, is mainly gas prone?', '["Type I","Type II","Type III","Type IV"]'::jsonb, 2, 'Type III is terrestrial and gas prone; Types I and II are oil prone; Type IV is inert.', 'petrolord', null),
  ('D1-025', 1, 'main', 3, 'Drilling', null, 'What is the normal hydrostatic gradient of fresh water?', '["0.1 psi/ft","1.0 psi/ft","0.433 psi/ft","0.052 psi/ft"]'::jsonb, 2, 'Fresh water exerts 0.433 psi per foot; salty formation water is a little more.', 'petrolord', null),
  ('D1-026', 1, 'main', 3, 'Geoscience', null, 'Flattening a correlation section on a datum changes what?', '["The structural relief","The zone thicknesses","The measured depths of the picks","Only the displayed depths"]'::jsonb, 3, 'Flattening is a display choice: it shifts each well on screen and changes no measurement.', 'nextgen', 'nextgen:wellcorrelation/intermediate/m03-displayed-depth/12'),
  ('D1-027', 1, 'main', 3, 'Geoscience', null, 'The deep Akata shales of the Niger Delta are known for being what?', '["Overpressured","Volcanic","Evaporites","Fractured granite"]'::jsonb, 0, 'The marine Akata shales are undercompacted and overpressured, which matters for drilling.', 'petrolord', null),
  ('D1-028', 1, 'main', 3, 'Economics', null, 'In the exceedance convention, what is a prospect''s P90 volume?', '["A volume with a 90% chance of being met or exceeded","The volume 90% of wells find","90% of the mean volume","The largest likely volume"]'::jsonb, 0, 'P90 is the low case: there is a 90% chance the outcome is at least this large.', 'petrolord', null),
  ('D1-029', 1, 'main', 3, 'Geoscience', null, 'On a structure map, what is the vertical closure of a trap?', '["The area of the licence","The height from the crest to the spill point","The depth of the oil-water contact","The reservoir thickness"]'::jsonb, 1, 'Closure is the relief between the highest point and the spill point.', 'petrolord', null),
  ('D1-030', 1, 'main', 3, 'Geoscience', null, 'Why use leave-one-well-out testing on a depth map?', '["To save computing time","To see how well the map predicts a well it has not seen","To delete bad wells for good","To smooth the map"]'::jsonb, 1, 'Removing one well, regridding and comparing gives an honest error at that well.', 'nextgen', 'nextgen:mapping/advanced/m02-leave-one-out/8'),
  ('D1-031', 1, 'main', 4, 'Geoscience', null, 'What does a Class III AVO gas sand typically show?', '["A positive amplitude that dims with offset","No change with offset","A strong negative amplitude that grows with offset","A phase reversal near zero amplitude"]'::jsonb, 2, 'Class III sands have lower impedance than the shale above, with a negative intercept and gradient.', 'petrolord', null),
  ('D1-032', 1, 'main', 4, 'Geoscience', null, 'In Gassmann fluid substitution, replacing brine with gas mainly changes what?', '["The bulk modulus","The grain size","The shear modulus","The mineral density"]'::jsonb, 0, 'Fluids carry no shear, so the shear modulus is unchanged; the bulk modulus drops.', 'petrolord', null),
  ('D1-033', 1, 'main', 4, 'Geoscience', null, 'Tuning thickness for a thin bed is about what fraction of the dominant wavelength?', '["The full wavelength","One half","One quarter","One tenth"]'::jsonb, 2, 'Top and base reflections interfere most at a quarter of a wavelength.', 'petrolord', null),
  ('D1-034', 1, 'main', 4, 'Drilling', null, 'Eaton''s method estimates pore pressure from what?', '["Log departure from the normal compaction trend","Mud weight alone","Gas readings only","Bit size"]'::jsonb, 0, 'Eaton compares sonic or resistivity with the normal compaction trend.', 'petrolord', null),
  ('D1-035', 1, 'main', 4, 'Economics', null, 'When is new information worth buying before a drilling decision?', '["Whenever it is seismic","When it is cheaper than a well","When the chance of success is above 50%","When it could change the decision"]'::jsonb, 3, 'Information has value only if some result would lead you to act differently.', 'petrolord', null),
  ('D1-036', 1, 'main', 4, 'Geoscience', null, 'Larionov (tertiary rocks): Vsh = 0.083 (2^(3.7 IGR) - 1). What is Vsh at IGR = 0.50?', '["0.30","0.22","0.50","0.08"]'::jsonb, 1, '2^1.85 = 3.61, so Vsh = 0.083 x 2.61 = 0.22.', 'nextgen', 'nextgen:petrophysics/beginner/m02-shale-volume/12'),
  ('D1-037', 1, 'main', 4, 'Geoscience', null, 'Kinetic maturity models such as Easy%Ro show that maturity depends on what?', '["Depth only","Temperature only","Temperature and time together","Pressure only"]'::jsonb, 2, 'A slow burial reaches the same maturity at a lower temperature than a fast one.', 'petrolord', null),
  ('D1-038', 1, 'main', 4, 'Geoscience', null, 'On a structure map, a gap in the horizon along a fault suggests what kind of fault?', '["A strike-slip fault","A normal fault","A reverse fault","An unconformity"]'::jsonb, 1, 'Extension pulls the blocks apart, leaving a gap (heave); reverse faults make an overlap.', 'petrolord', null),
  ('D1-039', 1, 'main', 4, 'Geoscience', null, 'On a Pickett plot of log Rt against log porosity, the water line has what slope?', '["+a, the tortuosity factor","Rw","-n, the saturation exponent","-m, the cementation exponent"]'::jsonb, 3, 'For Sw = 1, log Rt = log(a Rw) - m log(porosity), so the slope is -m.', 'petrolord', null),
  ('D1-040', 1, 'main', 5, 'Geoscience', null, 'Shuey: R = A + B sin^2(theta). A = -0.10 and B = -0.20. What is R at 30 degrees?', '["-0.30","-0.20","-0.05","-0.15"]'::jsonb, 3, 'sin^2(30) = 0.25, so R = -0.10 - 0.05 = -0.15.', 'petrolord', null),
  ('D1-041', 1, 'main', 5, 'Geoscience', null, 'Area 2 km2, gross thickness 30 m, net to gross 0.5. What is the net rock volume?', '["60 million m3","30 million m3","15 million m3","3 million m3"]'::jsonb, 1, '2,000,000 x 30 = 60 million m3 gross, x 0.5 = 30 million m3 net.', 'petrolord', null),
  ('D1-042', 1, 'main', 5, 'Reservoir', null, 'STOIIP = 7758 Ah porosity (1 - Sw) / Bo. Ah 1000 acre-ft, porosity 0.2, Sw 0.25, Bo 1.2?', '["About 0.97 million stb","1.40 million stb","1.16 million stb","0.32 million stb"]'::jsonb, 0, '7758 x 1000 x 0.2 x 0.75 / 1.2 = 969,750 stb.', 'petrolord', null),
  ('D1-043', 1, 'main', 5, 'Economics', null, 'Prior chance of success 0.35. A survey right 80% of the time reads success. New chance?', '["About 0.68","0.41","0.80","0.35"]'::jsonb, 0, '0.35 x 0.8 / (0.35 x 0.8 + 0.65 x 0.2) = 0.28 / 0.41 = 0.68.', 'nextgen', 'nextgen:decision/intermediate/m04-accuracy-and-value/2'),
  ('D1-044', 1, 'main', 5, 'Drilling', null, 'Pore pressure 4,680 psi at 9,000 ft TVD. What is the equivalent mud weight?', '["8.6 ppg","10.0 ppg","11.0 ppg","9.0 ppg"]'::jsonb, 1, '4680 / (0.052 x 9000) = 4680 / 468 = 10.0 ppg.', 'petrolord', null),
  ('D1-045', 1, 'main', 5, 'Geoscience', null, 'A 25 Hz wavelet travels at 3000 m/s. What is the approximate tuning thickness?', '["15 m","30 m","60 m","120 m"]'::jsonb, 1, 'Wavelength = 3000 / 25 = 120 m; a quarter of that is 30 m.', 'petrolord', null),
  ('D1-TB1', 1, 'tiebreak', 3, 'Geoscience', null, 'Archie: porosity 0.25, Rt 8 ohm.m, Rw 0.08, a 1, m 2, n 2. What is Sw?', '["40%","20%","64%","16%"]'::jsonb, 0, 'Sw = sqrt(0.08 / (0.0625 x 8)) = sqrt(0.16) = 0.40.', 'petrolord', null),
  ('D1-TB2', 1, 'tiebreak', 3, 'Geoscience', null, 'Two-way time 2400 ms, average velocity 2000 m/s. What depth is that?', '["4800 m","1200 m","2400 m","4000 m"]'::jsonb, 2, 'Depth = 2000 x 2.4 / 2 = 2400 m.', 'nextgen', 'nextgen:seismolord/beginner/m03-depth-to-time/6'),
  ('D1-TB3', 1, 'tiebreak', 4, 'Economics', null, 'Drill: 25% chance of +$200M, else -$40M. Farm out: 25% chance of +$60M, else 0. Which wins?', '["Drill, by $5M","Farm out, by $5M","Drill, by $20M","They are equal"]'::jsonb, 0, 'Drill EMV = 50 - 30 = $20M; farm out EMV = $15M.', 'petrolord', null),
  ('D1-TB4', 1, 'tiebreak', 4, 'Geoscience', null, 'A sand of impedance 6000 lies under shale of 8000. What is the reflection coefficient?', '["-0.25","-0.14","+0.14","-2000"]'::jsonb, 1, '(6000 - 8000) / (6000 + 8000) = -0.14.', 'petrolord', null),
  ('D1-TB5', 1, 'tiebreak', 5, 'Drilling', null, 'Eaton: overburden 1.0 psi/ft, pore 0.465 psi/ft, Poisson''s ratio 0.25. Fracture gradient?', '["0.64 psi/ft","0.47 psi/ft","0.82 psi/ft","1.00 psi/ft"]'::jsonb, 0, 'K = 0.25 / 0.75 = 0.333; FG = 0.333 x 0.535 + 0.465 = 0.64 psi/ft.', 'petrolord', null),
  ('D1-TB6', 1, 'tiebreak', 5, 'Reservoir', null, '640 acres, net pay 50 ft, porosity 0.25, Sw 0.2, Bo 1.25. What is the STOIIP?', '["62 million stb","32 million stb","About 40 million stb","50 million stb"]'::jsonb, 2, '7758 x 640 x 50 x 0.25 x 0.8 / 1.25 = 39.7 million stb.', 'petrolord', null),
  ('D2-001', 2, 'main', 1, 'Production', null, 'In artificial lift, what does ESP stand for?', '["Electrical submersible pump","Electric steam process","External sucker pump","Enhanced surface pressure"]'::jsonb, 0, 'An ESP is a multistage centrifugal pump driven by a downhole electric motor.', 'petrolord', null),
  ('D2-002', 2, 'main', 1, 'Production', null, 'What is water cut?', '["The water in the gas","The water injected each day","The fraction of water in the produced liquid","The water left in the reservoir"]'::jsonb, 2, 'Water cut = water rate / (oil rate + water rate).', 'petrolord', null),
  ('D2-003', 2, 'main', 1, 'Production', null, 'What does GOR stand for?', '["Gross oil recovery","Gas-oil ratio","Gas over reservoir","Gas output rate"]'::jsonb, 1, 'GOR is the produced gas per barrel of stock tank oil, usually in scf/stb.', 'petrolord', null),
  ('D2-004', 2, 'main', 1, 'Facilities', null, 'What is a production separator''s main job?', '["Measure reservoir pressure","Raise the well pressure","Split the well stream into oil, gas and water","Heat crude for refining"]'::jsonb, 2, 'Separators use gravity and residence time to split the phases.', 'petrolord', null),
  ('D2-005', 2, 'main', 1, 'Production', null, 'How does gas lift help a well flow?', '["It raises reservoir pressure","It lightens the fluid column in the tubing","It heats the reservoir","It plugs water zones"]'::jsonb, 1, 'Injected gas lowers the density of the column, so the reservoir can lift it.', 'petrolord', null),
  ('D2-006', 2, 'main', 1, 'Drilling', null, 'What is casing for?', '["Holding the hole open and isolating formations","Carrying the drill bit","Making the well flow faster","Measuring depth"]'::jsonb, 0, 'Cemented casing supports the hole and isolates zones from each other.', 'petrolord', null),
  ('D2-007', 2, 'main', 1, 'Production', null, 'What does a wellhead choke control?', '["The water salinity","The oil gravity","The flow rate","The reservoir temperature"]'::jsonb, 2, 'A choke is a restriction that sets the rate and the back pressure on the well.', 'petrolord', null),
  ('D2-008', 2, 'main', 1, 'Facilities', null, 'What is flaring?', '["Burning gas at a controlled stack","Venting crude to sea","Cooling gas into a liquid","Pumping gas into the reservoir"]'::jsonb, 0, 'Flaring burns gas that cannot be used or exported, and safely relieves pressure.', 'petrolord', null),
  ('D2-009', 2, 'main', 2, 'Production', null, 'A pump is installed and the oil rate jumps. What happened in the reservoir?', '["The pump added energy to the reservoir","The drive mechanism changed","Pressure rose above the bubble point","No new energy; the drawdown increased"]'::jsonb, 3, 'Lift lowers the flowing pressure at the sandface; reservoir pressure is unchanged.', 'nextgen', 'nextgen:dca/beginner/m01-declines-and-the-field/2'),
  ('D2-010', 2, 'main', 2, 'Production', null, 'What is special about an exponential decline?', '["The rate loses the same fraction in equal times","The rate stays flat, then stops","The rate falls by the same barrels each day","The rate rises before it falls"]'::jsonb, 0, 'Exponential decline has a constant decline rate D, so q = qi exp(-Dt).', 'nextgen', 'nextgen:dca/beginner/m02-the-three-models/1'),
  ('D2-011', 2, 'main', 2, 'Production', null, 'What is a well''s productivity index (PI)?', '["Water per unit of oil","Rate per unit of time","Pressure per unit of depth","Rate per unit of drawdown"]'::jsonb, 3, 'PI = q / (Pr - Pwf), for example in stb/d/psi.', 'petrolord', null),
  ('D2-012', 2, 'main', 2, 'Production', null, 'In nodal analysis, where is the operating point?', '["Where the choke is fully open","Where pressure is zero","Where the inflow and outflow curves cross","Where the rate is highest"]'::jsonb, 2, 'At the crossing, the reservoir delivers exactly what the tubing can carry.', 'petrolord', null),
  ('D2-013', 2, 'main', 2, 'Drilling', null, 'Mud of 10 ppg at 10,000 ft TVD. What is the hydrostatic pressure?', '["4,330 psi","52,000 psi","5,200 psi","520 psi"]'::jsonb, 2, '0.052 x 10 x 10,000 = 5,200 psi.', 'petrolord', null),
  ('D2-014', 2, 'main', 2, 'Production', null, 'What sign does the skin factor of a damaged well have?', '["Negative","Always zero","Positive","It has no sign"]'::jsonb, 2, 'Damage adds pressure drop near the well, which is a positive skin.', 'petrolord', null),
  ('D2-015', 2, 'main', 2, 'Production', null, 'Which lift method uses a beam and horsehead at surface?', '["Gas lift","Plunger lift","Electrical submersible pump","Rod pumping"]'::jsonb, 3, 'A beam pumping unit strokes sucker rods that drive a downhole pump.', 'petrolord', null),
  ('D2-016', 2, 'main', 2, 'Facilities', null, 'When do gas hydrates form in a pipeline?', '["Whenever the oil is waxy","Only in completely dry gas","At low temperature and high pressure with water present","At high temperature and low pressure"]'::jsonb, 2, 'Hydrates are ice-like solids of water and light gas that form cold and under pressure.', 'petrolord', null),
  ('D2-017', 2, 'main', 2, 'Production', null, 'Why does a gas well load up with liquid?', '["The gas rate is above the critical rate","The choke is fully open","The reservoir is above the dew point","The gas is too slow to carry liquid to surface"]'::jsonb, 3, 'Below the critical velocity, droplets fall back and build a liquid column.', 'petrolord', null),
  ('D2-018', 2, 'main', 2, 'Production', null, 'PI 2 stb/d/psi, reservoir 3,000 psi, flowing pressure 2,000 psi. What is the rate?', '["2,000 stb/d","1,000 stb/d","6,000 stb/d","4,000 stb/d"]'::jsonb, 0, 'q = PI x drawdown = 2 x 1,000 = 2,000 stb/d.', 'petrolord', null),
  ('D2-019', 2, 'main', 3, 'Production', null, 'When is the Vogel inflow relationship used?', '["When flowing pressure is below the bubble point","For a gas injector","When the well makes only water","Above the dew point"]'::jsonb, 0, 'Below the bubble point free gas forms and the inflow curve bends; Vogel describes that.', 'petrolord', null),
  ('D2-020', 2, 'main', 3, 'Production', null, 'Harmonic decline is the Arps case with b equal to what?', '["0.5","2","1","0"]'::jsonb, 2, 'b = 0 is exponential, 0 < b < 1 hyperbolic, and b = 1 harmonic.', 'petrolord', null),
  ('D2-021', 2, 'main', 3, 'Production', null, 'Exponential decline from 1,000 stb/d at 0.5 per year. What is the rate after 2 years?', '["500 stb/d","135 stb/d","250 stb/d","About 368 stb/d"]'::jsonb, 3, 'q = 1000 x exp(-0.5 x 2) = 1000 x exp(-1) = 368 stb/d.', 'petrolord', null),
  ('D2-022', 2, 'main', 3, 'Facilities', null, 'Which gas makes production fluids sour?', '["Hydrogen sulphide","Carbon dioxide","Methane","Nitrogen"]'::jsonb, 0, 'H2S makes fluids sour; CO2 makes them sweet-corrosive.', 'petrolord', null),
  ('D2-023', 2, 'main', 3, 'Production', null, 'What does a subsurface safety valve do?', '["Raises tubing pressure","Shuts the well in if surface control is lost","Injects chemicals","Measures the flow rate"]'::jsonb, 1, 'The SCSSV is held open by control line pressure and closes when it is lost.', 'petrolord', null),
  ('D2-024', 2, 'main', 3, 'Drilling', null, 'How many independent well barrier envelopes are normally required?', '["Three","Two","Four","One"]'::jsonb, 1, 'The two-barrier principle keeps a primary and a secondary envelope in place.', 'petrolord', null),
  ('D2-025', 2, 'main', 3, 'Production', null, 'A well test gives a skin of -3. What does that suggest?', '["A stimulated well, such as fractured or acidised","A well that cannot flow","Severe damage","A sealing fault"]'::jsonb, 0, 'Negative skin means less pressure drop near the well than an ideal open hole.', 'petrolord', null),
  ('D2-026', 2, 'main', 3, 'Facilities', null, 'Why is crude oil stabilised before export?', '["To raise its sulphur content","To cool it for storage only","To remove light ends so vapour pressure meets the spec","To add water for pumping"]'::jsonb, 2, 'Stabilisation strips light components so the crude is safe to store and ship.', 'petrolord', null),
  ('D2-027', 2, 'main', 3, 'Production', null, 'In a gas lift design, what fixes the depth of the top unloading valve?', '["Where the surface decrement runs out","Where injection pressure balances the kill fluid column and wellhead pressure","Where the gas rate peaks","The packer depth"]'::jsonb, 1, 'The top valve sits where the available injection pressure can just unload the kill fluid.', 'nextgen', 'nextgen:gaslift/beginner/m04-the-top-valve/1'),
  ('D2-028', 2, 'main', 3, 'Production', null, 'Every decline curve forecast assumes what?', '["Operating conditions and drive mechanism stay the same","Pressure stays above the bubble point","Water cut stays at zero","Rates have no scatter"]'::jsonb, 0, 'A workover, new lift or a change in drive makes the old curve describe a different well.', 'nextgen', 'nextgen:dca/beginner/m01-declines-and-the-field/4'),
  ('D2-029', 2, 'main', 3, 'Drilling', null, 'A perforating gun fires 6 shots per foot. How far apart are the shots?', '["6 inches","1 inch","2 inches","Half an inch"]'::jsonb, 2, '12 inches / 6 shots = 2 inches, a little over 5 cm.', 'nextgen', 'nextgen:perfsand/beginner/m03-the-geometry-the-charge-leaves/4'),
  ('D2-030', 2, 'main', 4, 'Production', null, 'For an ESP, what most directly raises the head each stage delivers?', '["A lower intake pressure","Running the pump faster","A higher water cut","Adding a gas separator"]'::jsonb, 1, 'By the affinity laws, head rises with the square of speed.', 'petrolord', null),
  ('D2-031', 2, 'main', 4, 'Production', null, 'By the pump affinity laws, doubling the speed multiplies the power by about what?', '["16","8","2","4"]'::jsonb, 1, 'Flow goes with speed, head with speed squared and power with speed cubed.', 'petrolord', null),
  ('D2-032', 2, 'main', 4, 'Facilities', null, 'By Stokes'' law, halving the droplet size changes its settling speed by what factor?', '["One quarter","Double","No change","One half"]'::jsonb, 0, 'Settling velocity is proportional to the droplet diameter squared.', 'petrolord', null),
  ('D2-033', 2, 'main', 4, 'Production', null, 'In hyperbolic decline with 0 < b < 1, what does the decline rate do?', '["Stays at zero","Stays constant","Falls as the rate falls","Rises over time"]'::jsonb, 2, 'The instantaneous decline rate is D = Di / (1 + b Di t), which falls with time.', 'petrolord', null),
  ('D2-034', 2, 'main', 4, 'Facilities', null, 'Paraffin crystallising below the wax appearance temperature causes what?', '["Hydrates","Wax deposition","Scale","Erosion"]'::jsonb, 1, 'Below the WAT, wax comes out of the oil and sticks to cold pipe walls.', 'petrolord', null),
  ('D2-035', 2, 'main', 4, 'Production', null, 'Barium sulphate scale often forms when what happens?', '["A well is shut in","Seawater mixes with barium-rich formation water","Oil is heated","Gas expands in the tubing"]'::jsonb, 1, 'Sulphate in injected seawater meets barium in formation water and precipitates.', 'petrolord', null),
  ('D2-036', 2, 'main', 4, 'Production', null, 'In a pressure buildup, the straight-line slope on a semilog plot gives what?', '["Reservoir size","Permeability-thickness, kh","Bubble point pressure","Skin only"]'::jsonb, 1, 'The radial flow slope m = 162.6 q B mu / kh gives kh.', 'petrolord', null),
  ('D2-037', 2, 'main', 4, 'Production', null, 'The field meter reads 9,000 stb/d; well tests add up to 10,000 stb/d. What is the allocation factor?', '["1.11","0.90","0.10","1.00"]'::jsonb, 1, 'Allocation factor = measured / theoretical = 9,000 / 10,000 = 0.90.', 'petrolord', null),
  ('D2-038', 2, 'main', 4, 'Facilities', null, 'Why is export gas dried with glycol (TEG)?', '["To add odour","To lower its water dew point against hydrates and corrosion","To remove H2S","To raise its heating value"]'::jsonb, 1, 'TEG absorbs water vapour so free water cannot drop out in the pipeline.', 'petrolord', null),
  ('D2-039', 2, 'main', 5, 'Production', null, 'Exponential decline took a well from 800 to 400 stb/d in 2 years. What is the nominal decline?', '["0.50 per year","0.69 per year","0.25 per year","About 0.35 per year"]'::jsonb, 3, 'D = ln(800 / 400) / 2 = 0.693 / 2 = 0.35 per year.', 'petrolord', null),
  ('D2-040', 2, 'main', 5, 'Production', null, 'Exponential: qi 1,000 stb/d, limit 100 stb/d, D = 0.001 per day. What are the reserves?', '["900,000 stb","9,000,000 stb","90,000 stb","1,000,000 stb"]'::jsonb, 0, 'EUR = (qi - q limit) / D = 900 / 0.001 = 900,000 stb.', 'nextgen', 'nextgen:dca/beginner/m05-eur-and-the-limit/4'),
  ('D2-041', 2, 'main', 5, 'Production', null, 'Which formula gives cumulative oil for a harmonic decline?', '["Np = (qi/Di)(1 - exp(-Di t))","Np = (qi/Di) ln(Di t)","Np = qi t","Np = (qi/Di) ln(1 + Di t)"]'::jsonb, 3, 'Integrating q = qi / (1 + Di t) gives (qi/Di) ln(1 + Di t).', 'nextgen', 'nextgen:dca/beginner/m03-cumulative-volumes/1'),
  ('D2-042', 2, 'main', 5, 'Production', null, 'Vogel: maximum rate 3,000 stb/d. What is the rate at half the reservoir pressure?', '["1,500 stb/d","1,800 stb/d","2,100 stb/d","2,250 stb/d"]'::jsonb, 2, '1 - 0.2 x 0.5 - 0.8 x 0.25 = 0.7, and 0.7 x 3,000 = 2,100.', 'petrolord', null),
  ('D2-043', 2, 'main', 5, 'Drilling', null, 'Mud 10 ppg, annular friction 260 psi at 10,000 ft TVD. What is the ECD?', '["10.5 ppg","10.26 ppg","12.6 ppg","10.05 ppg"]'::jsonb, 0, 'ECD = 10 + 260 / (0.052 x 10,000) = 10 + 0.5 = 10.5 ppg.', 'petrolord', null),
  ('D2-044', 2, 'main', 5, 'Facilities', null, 'Souders-Brown: doubling the K factor changes the allowable gas velocity how?', '["No change","It halves","It quadruples","It doubles"]'::jsonb, 3, 'V = K sqrt((rho L - rho G) / rho G), so the velocity is proportional to K.', 'petrolord', null),
  ('D2-045', 2, 'main', 5, 'Production', null, 'A well makes 1,200 bbl/d of liquid at 75% water cut and GOR 500 scf/stb. Gas rate?', '["150 Mscf/d","37.5 Mscf/d","600 Mscf/d","450 Mscf/d"]'::jsonb, 0, 'Oil = 300 stb/d, and 300 x 500 = 150,000 scf/d.', 'petrolord', null),
  ('D2-TB1', 2, 'tiebreak', 3, 'Drilling', null, 'Mud of 12 ppg at 8,000 ft TVD. What is the hydrostatic pressure?', '["5,760 psi","499 psi","4,992 psi","4,160 psi"]'::jsonb, 2, '0.052 x 12 x 8,000 = 4,992 psi.', 'petrolord', null),
  ('D2-TB2', 2, 'tiebreak', 3, 'Production', null, 'PI 1.5 stb/d/psi, reservoir 2,800 psi, rate 1,200 stb/d. What is the flowing pressure?', '["1,600 psi","2,400 psi","800 psi","2,000 psi"]'::jsonb, 3, 'Drawdown = 1,200 / 1.5 = 800 psi, so Pwf = 2,800 - 800 = 2,000 psi.', 'petrolord', null),
  ('D2-TB3', 2, 'tiebreak', 4, 'Production', null, 'Liquid 2,000 bbl/d at 60% water cut, GOR 800 scf/stb. What is the gas rate?', '["960 Mscf/d","1,280 Mscf/d","640 Mscf/d","1,600 Mscf/d"]'::jsonb, 2, 'Oil = 800 stb/d, and 800 x 800 = 640,000 scf/d.', 'petrolord', null),
  ('D2-TB4', 2, 'tiebreak', 4, 'Production', null, 'Exponential decline at 0.2 per year. What share of the rate is left after 5 years?', '["None","About 37%","20%","50%"]'::jsonb, 1, 'exp(-0.2 x 5) = exp(-1) = 0.37.', 'petrolord', null),
  ('D2-TB5', 2, 'tiebreak', 5, 'Production', null, 'Vogel: maximum rate 2,000 stb/d. What is the rate at a quarter of reservoir pressure?', '["1,650 stb/d","1,875 stb/d","1,500 stb/d","1,800 stb/d"]'::jsonb, 3, '1 - 0.2 x 0.25 - 0.8 x 0.0625 = 0.90, and 0.90 x 2,000 = 1,800.', 'petrolord', null),
  ('D2-TB6', 2, 'tiebreak', 5, 'Facilities', null, 'A 100 micron droplet settles at 0.2 ft/min. How fast does a 50 micron droplet settle?', '["0.05 ft/min","0.1 ft/min","0.025 ft/min","0.4 ft/min"]'::jsonb, 0, 'Stokes: velocity goes with diameter squared, so 0.2 x 0.25 = 0.05 ft/min.', 'petrolord', null),
  ('D3-001', 3, 'main', 1, 'Reservoir', null, 'What does STOIIP stand for?', '["Standard total oil in production","Stock tank oil in pipelines","Static oil in place","Stock tank oil initially in place"]'::jsonb, 3, 'STOIIP is the oil in the reservoir at discovery, expressed at stock tank conditions.', 'petrolord', null),
  ('D3-002', 3, 'main', 1, 'Reservoir', null, 'What is the recovery factor?', '["The porosity cutoff","The water cut at abandonment","The rate per well","The share of the in-place volume that is produced"]'::jsonb, 3, 'Recovery factor = recoverable volume / volume in place.', 'petrolord', null),
  ('D3-003', 3, 'main', 1, 'Reservoir', null, 'What is waterflooding?', '["Flooding a well to kill it","Producing only water","Injecting water to push oil and hold up pressure","Washing out a separator"]'::jsonb, 2, 'Water injection maintains pressure and sweeps oil towards producers.', 'petrolord', null),
  ('D3-004', 3, 'main', 1, 'Economics', null, 'What does NPV stand for?', '["Net present value","Net petroleum value","Nominal price variance","New production volume"]'::jsonb, 0, 'NPV is the sum of future cash flows discounted to today.', 'petrolord', null),
  ('D3-005', 3, 'main', 1, 'Reservoir', null, 'Which drive mechanism comes from a large connected body of water?', '["Water drive","Gas cap drive","Solution gas drive","Gravity drainage"]'::jsonb, 0, 'As pressure falls, the aquifer expands and pushes water into the oil zone.', 'petrolord', null),
  ('D3-006', 3, 'main', 1, 'Reservoir', null, 'What is porosity?', '["The share of rock volume that is pore space","The rock''s density","The water share of the pores","How easily fluid flows"]'::jsonb, 0, 'Porosity is pore volume divided by bulk volume.', 'petrolord', null),
  ('D3-007', 3, 'main', 1, 'Economics', null, 'In field development, what does FDP stand for?', '["Final drilling permit","Flow design procedure","Field development plan","Facility demand projection"]'::jsonb, 2, 'The FDP sets out how a discovery will be developed and produced.', 'petrolord', null),
  ('D3-008', 3, 'main', 1, 'Reservoir', null, 'Which unit is permeability usually measured in?', '["Pascals","Millidarcies","Barrels","API degrees"]'::jsonb, 1, 'Permeability is quoted in darcies or, more often, millidarcies.', 'petrolord', null),
  ('D3-009', 3, 'main', 2, 'Reservoir', null, 'What value does the oil formation volume factor Bo usually have?', '["More than 1 rb/stb","Below zero","Exactly 1 rb/stb","Less than 1 rb/stb"]'::jsonb, 0, 'Reservoir oil carries dissolved gas and shrinks at surface, so Bo is above 1.', 'petrolord', null),
  ('D3-010', 3, 'main', 2, 'Reservoir', null, 'Above its bubble point, what state is reservoir oil in?', '["Undersaturated, with all its gas dissolved","Below its dew point","Producing free gas","A gas condensate"]'::jsonb, 0, 'No free gas forms until pressure drops to the bubble point.', 'petrolord', null),
  ('D3-011', 3, 'main', 2, 'Economics', null, 'A higher discount rate does what to the NPV of a typical oil project?', '["Always makes it negative","Raises it","Leaves it unchanged","Lowers it"]'::jsonb, 3, 'Later cash inflows are worth less today when the discount rate rises.', 'petrolord', null),
  ('D3-012', 3, 'main', 2, 'Reservoir', null, 'Which question can material balance NOT answer?', '["How much volume production has vacated","What next year''s production rate will be","How much the oil has expanded","How much oil was originally in place"]'::jsonb, 1, 'Material balance is a volume balance with no time or rate in it; rates need a flow model.', 'nextgen', 'nextgen:mbal/beginner/m01-the-tank-idea/3'),
  ('D3-013', 3, 'main', 2, 'Reservoir', null, 'What does relative permeability describe?', '["Permeability change with depth","How easily each fluid flows when several share the pores","One rock''s permeability against another","Fracture spacing"]'::jsonb, 1, 'Each phase flows less freely when other phases occupy part of the pore space.', 'petrolord', null),
  ('D3-014', 3, 'main', 2, 'Reservoir', null, 'In a waterflood, what does the mobility ratio compare?', '["Oil and gas densities","Water mobility behind the front with oil mobility ahead","The PI of two wells","Injection and production rates"]'::jsonb, 1, 'M = (krw / muw) / (kro / muo); M at or below 1 is favourable.', 'petrolord', null),
  ('D3-015', 3, 'main', 2, 'Economics', null, 'What is the payback period?', '["The life of the field","The time to first oil","The time until cumulative cash flow turns positive","The loan term"]'::jsonb, 2, 'Payback is when the project has earned back what was spent.', 'petrolord', null),
  ('D3-016', 3, 'main', 2, 'Reservoir', null, 'What is history matching in reservoir simulation?', '["Tuning the model until it reproduces past production and pressure","Copying another field''s model","Forecasting with no data","Matching the oil price history"]'::jsonb, 0, 'A model that matches the past is more credible for forecasting.', 'petrolord', null),
  ('D3-017', 3, 'main', 2, 'Reservoir', null, 'For a water-wet rock, what is drainage?', '["Water saturation increasing","Any oil production from the rock","Flow driven by gravity alone","Water saturation decreasing"]'::jsonb, 3, 'Drainage is the non-wetting phase displacing the wetting phase; imbibition is the reverse.', 'nextgen', 'nextgen:scal/beginner/m01-two-phases-one-rock/6'),
  ('D3-018', 3, 'main', 2, 'Assurance', null, 'Under the Petroleum Industry Act 2021, which body regulates midstream and downstream?', '["NUPRC","NCDMB","NMDPRA","NNPC Limited"]'::jsonb, 2, 'The Nigerian Midstream and Downstream Petroleum Regulatory Authority.', 'petrolord', null),
  ('D3-019', 3, 'main', 3, 'Reservoir', null, 'Ah 5,000 acre-ft, porosity 0.2, Sw 0.3, Bo 1.4. What is the STOIIP?', '["7.6 million stb","About 3.9 million stb","5.4 million stb","1.7 million stb"]'::jsonb, 1, '7758 x 5,000 x 0.2 x 0.7 / 1.4 = 3.88 million stb.', 'petrolord', null),
  ('D3-020', 3, 'main', 3, 'Reservoir', null, 'Which drive mechanism usually gives the lowest primary oil recovery?', '["Gravity drainage","Strong water drive","Solution gas drive","Gas cap drive"]'::jsonb, 2, 'Solution gas drive often recovers only 5 to 30%; strong water drive can exceed 50%.', 'petrolord', null),
  ('D3-021', 3, 'main', 3, 'Reservoir', null, 'On a fractional flow curve, what does the Welge tangent give?', '["The residual oil saturation","The critical gas saturation","The water saturation at the flood front","The initial water saturation"]'::jsonb, 2, 'The tangent from the initial saturation touches the curve at the front saturation.', 'petrolord', null),
  ('D3-022', 3, 'main', 3, 'Economics', null, 'What is a project''s internal rate of return (IRR)?', '["The rate at payback","The discount rate at which NPV is zero","The rate at which NPV is highest","The rate capex is spent"]'::jsonb, 1, 'IRR is the discount rate that makes the NPV exactly zero.', 'petrolord', null),
  ('D3-023', 3, 'main', 3, 'Reservoir', null, 'An early unit slope on a log-log well test plot indicates what?', '["Linear flow","A sealing fault","Wellbore storage","Infinite-acting radial flow"]'::jsonb, 2, 'At early time the wellbore fills or empties, giving pressure proportional to time.', 'petrolord', null),
  ('D3-024', 3, 'main', 3, 'Reservoir', null, 'On a pressure derivative plot, how does infinite-acting radial flow appear?', '["A flat line","A half slope","A downward spike","A unit slope"]'::jsonb, 0, 'Radial flow gives a constant derivative, the plateau used to read kh.', 'petrolord', null),
  ('D3-025', 3, 'main', 3, 'Economics', null, 'Nominal discount rate 10% with 3% inflation. What is the real rate?', '["13%","3%","7.7%","About 6.8%"]'::jsonb, 3, '1.10 / 1.03 - 1 = 0.068.', 'petrolord', null),
  ('D3-026', 3, 'main', 3, 'Reservoir', null, 'What explains the water saturation transition zone above the free water level?', '["Capillary pressure","Oil viscosity","Gas compressibility","Water coning"]'::jsonb, 0, 'Capillary forces hold water up in small pores, so saturation changes gradually with height.', 'petrolord', null),
  ('D3-027', 3, 'main', 3, 'Reservoir', null, 'The Efw term in the material balance equation bundles which two effects?', '["Oil and dissolved water expansion","Aquifer influx and water expansion","Grain shrinkage and clay swelling","Pore compaction and connate water expansion"]'::jsonb, 3, 'Efw covers the rock and connate water expansion as pressure falls.', 'nextgen', 'nextgen:mbal/beginner/m02-the-terms/8'),
  ('D3-028', 3, 'main', 3, 'Economics', null, 'What does a tornado chart show?', '["Well locations","Which inputs swing the result most","Wind loads on platforms","Cash flow by year"]'::jsonb, 1, 'Each bar shows how far the result moves when one input goes from low to high.', 'petrolord', null),
  ('D3-029', 3, 'main', 3, 'Reservoir', null, 'What is upscaling in reservoir modelling?', '["Raising the price deck","Drilling deeper","Averaging fine-scale properties onto a coarser simulation grid","Adding more wells"]'::jsonb, 2, 'Geological models are too fine to simulate, so properties are averaged onto coarser cells.', 'petrolord', null),
  ('D3-030', 3, 'main', 4, 'Reservoir', null, 'A waterflood with a mobility ratio well above 1 tends to cause what?', '["Better sweep","A piston-like front","Viscous fingering and early breakthrough","A lower water cut"]'::jsonb, 2, 'Water moves more easily than the oil and fingers through it.', 'petrolord', null),
  ('D3-031', 3, 'main', 4, 'Reservoir', null, 'In the industry exceedance convention, what is P10?', '["The low case","The high case, exceeded only 10% of the time","The mean","The most likely case"]'::jsonb, 1, 'P90 is the low case and P10 the high case.', 'petrolord', null),
  ('D3-032', 3, 'main', 4, 'Reservoir', null, 'A straight p/z against cumulative gas line is expected for what?', '["Any gas well","A volumetric gas reservoir with no water influx","A strong water drive gas reservoir","An oil reservoir"]'::jsonb, 1, 'With no influx, p/z falls linearly; aquifer support bends the line upwards.', 'petrolord', null),
  ('D3-033', 3, 'main', 4, 'Reservoir', null, 'In the STOIIP formula, what does the 7758 convert?', '["Barrels to cubic feet","Acre-feet to barrels","Feet to metres","psi to bar"]'::jsonb, 1, 'One acre-foot holds about 7,758 barrels.', 'petrolord', null),
  ('D3-034', 3, 'main', 4, 'Economics', null, 'In a production sharing contract, what is cost oil?', '["Oil the contractor takes to recover its costs","Oil lost in pipelines","Oil burned as fuel","Oil sold at cost price"]'::jsonb, 0, 'Cost oil repays allowed costs; the remainder is profit oil, shared with the state.', 'petrolord', null),
  ('D3-035', 3, 'main', 4, 'Reservoir', null, 'The Leverett J-function scales capillary pressure using what?', '["Depth alone","Oil density","Porosity alone","The square root of permeability over porosity"]'::jsonb, 3, 'J = Pc sqrt(k / porosity) / (sigma cos theta) lets one curve serve many rocks.', 'petrolord', null),
  ('D3-036', 3, 'main', 4, 'Reservoir', null, 'What does the Dykstra-Parsons coefficient measure?', '["Water salinity","How variable permeability is between layers","Well spacing","Oil viscosity"]'::jsonb, 1, 'It ranges from 0 (uniform) towards 1 (very heterogeneous).', 'petrolord', null),
  ('D3-037', 3, 'main', 4, 'Reservoir', null, 'Why does the basic Buckley-Leverett solution give a sharp flood front?', '["Water is treated as compressible","It neglects capillary pressure","It includes gravity along dip","The sand is layered"]'::jsonb, 1, 'Capillary pressure would smear the front over a transition zone.', 'nextgen', 'nextgen:scal/beginner/m06-the-associate-reading/5'),
  ('D3-038', 3, 'main', 4, 'Reservoir', null, 'What is a gas well''s absolute open flow (AOF)?', '["The rate with the choke fully open","The highest rate actually tested","The rate if flowing pressure were brought to atmospheric","The highest safe rate for the completion"]'::jsonb, 2, 'AOF is a theoretical maximum used to compare wells.', 'nextgen', 'nextgen:welltest/advanced/m04-gas/14'),
  ('D3-039', 3, 'main', 5, 'Reservoir', null, 'Volumetric gas: p/z falls from 5,000 to 4,000 psia after 20 Bscf. What is the GIIP?', '["120 Bscf","100 Bscf","25 Bscf","80 Bscf"]'::jsonb, 1, '20% of p/z is gone, so 20 Bscf is 20% of the gas: GIIP = 100 Bscf.', 'petrolord', null),
  ('D3-040', 3, 'main', 5, 'Economics', null, 'At 10%: -$100M now, +$60M in year 1 and +$60M in year 2. What is the NPV?', '["-$4M","About +$4M","+$9M","+$20M"]'::jsonb, 1, '60 / 1.1 + 60 / 1.21 - 100 = 54.5 + 49.6 - 100 = +$4.1M.', 'petrolord', null),
  ('D3-041', 3, 'main', 5, 'Reservoir', null, 'In radial flow, re/rw rises from 1,000 to 2,000. How does the rate change?', '["It falls by about 9%","It halves","No change","It doubles"]'::jsonb, 0, 'Rate goes with 1 / ln(re/rw): ln 1000 = 6.91, ln 2000 = 7.60, a ratio of 0.91.', 'petrolord', null),
  ('D3-042', 3, 'main', 5, 'Reservoir', null, 'Undersaturated oil: Np 1 MMstb, Boi 1.30, Bo 1.32, rock and water ignored. What is N?', '["132 million stb","66 million stb","50 million stb","76 million stb"]'::jsonb, 1, 'N = Np Bo / (Bo - Boi) = 1 x 1.32 / 0.02 = 66 MMstb.', 'petrolord', null),
  ('D3-043', 3, 'main', 5, 'Economics', null, 'Capex $300M, opex $10/bbl, 30 MMbbl recovered, no tax or discounting. Breakeven price?', '["$20/bbl","$10/bbl","$15/bbl","$30/bbl"]'::jsonb, 0, '300 / 30 = $10/bbl of capex plus $10/bbl opex.', 'petrolord', null),
  ('D3-044', 3, 'main', 5, 'Reservoir', null, 'Areal sweep 0.7, vertical sweep 0.8, displacement efficiency 0.6. Overall recovery efficiency?', '["56%","About 34%","60%","70%"]'::jsonb, 1, '0.7 x 0.8 x 0.6 = 0.336.', 'petrolord', null),
  ('D3-045', 3, 'main', 5, 'Reservoir', null, 'What is material-balance time in rate transient analysis?', '["Cumulative production divided by the current rate","Cumulative production divided by the initial rate","Time to abandonment","Elapsed time weighted by rate"]'::jsonb, 0, 'tMB = Np / q turns a variable-rate history into an equivalent constant-rate one.', 'nextgen', 'nextgen:welltest/advanced/m05-rate-transient-analysis/3'),
  ('D3-046', 3, 'main', 2, 'Facilities', null, 'In offshore field development, what does FPSO stand for?', '["Fixed platform for subsea operations","Floating production, storage and offloading","Floating pipeline service operation","Field production system offshore"]'::jsonb, 1, 'An FPSO processes and stores oil on a ship-shaped hull and offloads it to tankers.', 'petrolord', null),
  ('D3-047', 3, 'main', 3, 'Facilities', null, 'Why is a field''s plant often sized for a plateau below the wells'' combined peak?', '["Pipelines cannot carry more oil","Wells can never exceed the plateau","Regulators forbid peak rates","A smaller plant run full for longer usually gives more value"]'::jsonb, 3, 'Sizing for the brief early peak buys capacity that sits idle for most of the field life.', 'petrolord', null),
  ('D3-048', 3, 'main', 4, 'Facilities', null, 'What does tying a new field back to an existing host platform mainly save?', '["Reservoir pressure","The need for any pipeline","The cost of a new processing facility","The number of wells"]'::jsonb, 2, 'A subsea tieback uses the host''s spare processing capacity instead of building a new plant.', 'petrolord', null),
  ('D3-TB1', 3, 'tiebreak', 3, 'Economics', null, 'What is the discount factor for a cash flow 3 years away at 10%?', '["0.700","0.751","0.769","0.909"]'::jsonb, 1, '1 / 1.1^3 = 1 / 1.331 = 0.751.', 'petrolord', null),
  ('D3-TB2', 3, 'tiebreak', 3, 'Reservoir', null, 'Ah 2,000 acre-ft, porosity 0.25, Sw 0.2, Bo 1.0. What is the STOIIP?', '["3.1 million stb","3.9 million stb","1.55 million stb","0.78 million stb"]'::jsonb, 0, '7758 x 2,000 x 0.25 x 0.8 = 3.10 million stb.', 'petrolord', null),
  ('D3-TB3', 3, 'tiebreak', 4, 'Reservoir', null, 'Volumetric gas: p/z falls from 4,500 to 3,600 psia after 15 Bscf. What is the GIIP?', '["75 Bscf","60 Bscf","18.75 Bscf","90 Bscf"]'::jsonb, 0, 'p/z fell 20%, so 15 Bscf is 20% of the gas: 75 Bscf.', 'petrolord', null),
